    JSON.stringify(handlers.createOrderHandler({ id: 'ord_abcd1237', total: 5, createdAt: 'yesterday' })));
  setImmediate(() => console.log('stored createdAt:', store.orders.find((o) => o.id === 'ord_abcd1237').createdAt));
});

